def pull(trans, lang, fname):
  count = 0
  print "Updating %s from Transifex...\n" % fname,
  sys.stdout.flush()
  while count < 5:
    count += 1
    try:
      trans.pull(lang, fname)
      return
    except requests.exceptions.HTTPError, e:
      print " *** Retrying %s from Transifex...\n" % fname,
      time.sleep(3)
      sys.stdout.flush()

  if count >= 5:
    raise Exception("Too many retries")
